// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {FixedPoint96} from "@uniswap/v4-core/src/libraries/FixedPoint96.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";

/// @notice Provides functions for computing liquidity amounts from token amounts and prices
library LiquidityAmounts {
    using SafeCast for uint256;

    /// @notice Computes the amount of liquidity received for a given amount of token0 and price range
    /// @dev Calculates amount0 * (sqrt(upper) * sqrt(lower)) / (sqrt(upper) - sqrt(lower))
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount0 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount0(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount0)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            uint256 intermediate = FullMath.mulDiv(sqrtPriceAX96, sqrtPriceBX96, FixedPoint96.Q96);
            return FullMath.mulDiv(amount0, intermediate, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the amount of liquidity received for a given amount of token1 and price range
    /// @dev Calculates amount1 / (sqrt(upper) - sqrt(lower)).
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount1 The amount1 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount1(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount1)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            return FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the maximum amount of liquidity received for a given amount of token0, token1, the current
    /// pool prices and the prices at the tick boundaries
    /// @param sqrtPriceX96 A sqrt price representing the current pool prices
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount of token0 being sent in
    /// @param amount1 The amount of token1 being sent in
    /// @return liquidity The maximum amount of liquidity received
    function getLiquidityForAmounts(
        uint160 sqrtPriceX96,
        uint160 sqrtPriceAX96,
        uint160 sqrtPriceBX96,
        uint256 amount0,
        uint256 amount1
    ) internal pure returns (uint128 liquidity) {
        if (sqrtPriceAX96 > sqrtPriceBX96) {
            (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
        }

        if (sqrtPriceX96 <= sqrtPriceAX96) {
            liquidity = getLiquidityForAmount0(sqrtPriceAX96, sqrtPriceBX96, amount0);
        } else if (sqrtPriceX96 < sqrtPriceBX96) {
            uint128 liquidity0 = getLiquidityForAmount0(sqrtPriceX96, sqrtPriceBX96, amount0);
            uint128 liquidity1 = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceX96, amount1);

            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        } else {
            liquidity = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceBX96, amount1);
        }
    }
}

lib/v4-periphery/src/libraries/PositionI.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId} from "@uniswap/v4-core/src/types/PoolId.sol";

/**
 * @dev PositionInfo is a packed version of solidity structure.
 * Using the packaged version saves gas and memory by not storing the structure fields in memory slots.
 *
 * Layout:
 * 200 bits poolId | 24 bits tickUpper | 24 bits tickLower | 8 bits hasSubscriber
 *
 * Fields in the direction from the least significant bit:
 *
 * A flag to know if the tokenId is subscribed to an address
 * uint8 hasSubscriber;
 *
 * The tickUpper of the position
 * int24 tickUpper;
 *
 * The tickLower of the position
 * int24 tickLower;
 *
 * The truncated poolId. Truncates a bytes32 value so the most signifcant (highest) 200 bits are used.
 * bytes25 poolId;
 *
 * Note: If more bits are needed, hasSubscriber can be a single bit.
 *
 */
type PositionInfo is uint256;

using PositionInfoLibrary for PositionInfo global;

library PositionInfoLibrary {
    PositionInfo internal constant EMPTY_POSITION_INFO = PositionInfo.wrap(0);

    uint256 internal constant MASK_UPPER_200_BITS = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF00000000000000;
    uint256 internal constant MASK_8_BITS = 0xFF;
    uint24 internal constant MASK_24_BITS = 0xFFFFFF;
    uint256 internal constant SET_UNSUBSCRIBE = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF00;
    uint256 internal constant SET_SUBSCRIBE = 0x01;
    uint8 internal constant TICK_LOWER_OFFSET = 8;
    uint8 internal constant TICK_UPPER_OFFSET = 32;

    /// @dev This poolId is NOT compatible with the poolId used in UniswapV4 core. It is truncated to 25 bytes, and just used to lookup PoolKey in the poolKeys mapping.
    function poolId(PositionInfo info) internal pure returns (bytes25 _poolId) {
        assembly ("memory-safe") {
            _poolId := and(MASK_UPPER_200_BITS, info)
        }
    }

    function tickLower(PositionInfo info) internal pure returns (int24 _tickLower) {
        assembly ("memory-safe") {
            _tickLower := signextend(2, shr(TICK_LOWER_OFFSET, info))
        }
    }

    function tickUpper(PositionInfo info) internal pure returns (int24 _tickUpper) {
        assembly ("memory-safe") {
            _tickUpper := signextend(2, shr(TICK_UPPER_OFFSET, info))
        }
    }

    function hasSubscriber(PositionInfo info) internal pure returns (bool _hasSubscriber) {
        assembly ("memory-safe") {
            _hasSubscriber := and(MASK_8_BITS, info)
        }
    }

    /// @dev this does not actually set any storage
    function setSubscribe(PositionInfo info) internal pure returns (PositionInfo _info) {
        assembly ("memory-safe") {
            _info := or(info, SET_SUBSCRIBE)
        }
    }

    /// @dev this does not actually set any storage
    function setUnsubscribe(PositionInfo info) internal pure returns (PositionInfo _info) {
        assembly ("memory-safe") {
            _info := and(info, SET_UNSUBSCRIBE)
        }
    }

    /// @notice Creates the default PositionInfo struct
    /// @dev Called when minting a new position
    /// @param _poolKey the pool key of the position
    /// @param _tickLower the lower tick of the position
    /// @param _tickUpper the upper tick of the position
    /// @return info packed position info, with the truncated poolId and the hasSubscriber flag set to false
    function initialize(PoolKey memory _poolKey, int24 _tickLower, int24 _tickUpper)
        internal
        pure
        returns (PositionInfo info)
    {
        bytes25 _poolId = bytes25(PoolId.unwrap(_poolKey.toId()));
        assembly {
            info := or(
                or(and(MASK_UPPER_200_BITS, _poolId), shl(TICK_UPPER_OFFSET, and(MASK_24_BITS, _tickUpper))),
                shl(TICK_LOWER_OFFSET, and(MASK_24_BITS, _tickLower))
            )
        }
    }
}

src/PadCoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

/// @title ArkhamPadCoin
/// @notice A coin created on ArkhamPad (arkhampad.com). The whole supply is minted
/// once at creation, to ArkhamPad's pool builder, which puts all of it into the
/// coin's locked Uniswap pool. There is no owner and no way to mint more.
///
/// Optional creator lock: until `unlockTime`, the creator's own wallet cannot
/// move or sell this coin. It can still receive (buy) more. The lock length is
/// chosen at launch, can never be changed and is at most one day.
/// Supports EIP-2612 permit, so holders can approve by signature (no gas).
contract ArkhamPadCoin is ERC20, ERC20Permit {
    uint256 public constant MAX_LOCK = 1 days;

    address public immutable creator;
    uint256 public immutable unlockTime;
    /// @notice Link to the coin's metadata (image, description, socials).
    string public metadataURI;

    error CreatorLocked(uint256 unlockTime);
    error LockTooLong();

    constructor(
        string memory name_,
        string memory symbol_,
        string memory metadataURI_,
        uint256 supply,
        address mintTo,
        address creator_,
        uint256 lockSeconds
    ) ERC20(name_, symbol_) ERC20Permit(name_) {
        if (lockSeconds > MAX_LOCK) revert LockTooLong();
        creator = creator_;
        unlockTime = lockSeconds == 0 ? 0 : block.timestamp + lockSeconds;
        metadataURI = metadataURI_;
        _mint(mintTo, supply);
    }

    function isLocked() public view returns (bool) {
        return block.timestamp < unlockTime;
    }

    function _update(address from, address to, uint256 value) internal override {
        if (from == creator && from != address(0) && block.timestamp < unlockTime) revert CreatorLocked(unlockTime);
        super._update(from, to, value);
    }
}

src/PadHub.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ArkhamPadCoin} from "./PadCoin.sol";
import {FeeMode} from "./PadTypes.sol";
import {IPadPoolBuilder} from "./interfaces.sol";

/// @title PadHub
/// @notice Creates ArkhamPad coins on one chain and keeps the few settings
/// they share. Launching is free; the creator may buy in the same transaction.
///
/// Every coin goes straight into a Uniswap v4 pool at launch: the whole supply
/// (1 billion coins, minted once, no owner, no minting later) becomes locked
/// liquidity that starts at `startMarketCap` and covers every higher price.
///
/// Roles:
///   admin    - sets the treasury, the guardian and can pause/unpause launches.
///              Two-step transfer. Cannot touch any coin's or user's funds.
///   guardian - can only pause new launches (for emergencies). Only the admin
///              unpauses. Trading in the pools can never be paused by anyone.
contract PadHub is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant SUPPLY = 1_000_000_000e18;

    IERC20 public immutable usdc;
    IPadPoolBuilder public immutable poolBuilder;
    /// @notice Launch market cap in USDC (the dollar token's own decimals) for the whole supply.
    uint256 public immutable startMarketCap;
    /// @notice Every launch includes a creator buy of at least this much (the dollar token's
    /// own decimals): the pool's first trade happens at launch, so the coin shows up on DEX
    /// screeners right away, and only people who actually put money in can launch.
    uint256 public immutable minLaunchBuy;

    address public admin;
    address public pendingAdmin;
    address public guardian;
    address public treasury;
    address public router;
    bool public buysPaused;

    mapping(address => bool) public isCoin;
    address[] public allCoins;

    event CoinCreated(
        address indexed coin,
        address indexed creator,
        string name,
        string symbol,
        string metadataURI,
        uint256 lockSeconds,
        FeeMode feeMode
    );
    event TreasuryChanged(address treasury);
    event GuardianChanged(address guardian);
    event AdminProposed(address admin);
    event AdminChanged(address admin);
    event BuysPaused(bool paused);
    event RouterChanged(address router);

    error NotAdmin();
    error NotAllowed();
    error ZeroAddress();
    error BadName();
    error LaunchBuyTooSmall(uint256 minimum);

    constructor(
        IERC20 usdc_,
        IPadPoolBuilder poolBuilder_,
        uint256 startMarketCap_,
        uint256 minLaunchBuy_,
        address admin_,
        address treasury_
    ) {
        if (address(usdc_) == address(0) || address(poolBuilder_) == address(0) || admin_ == address(0) || treasury_ == address(0)) {
            revert ZeroAddress();
        }
        usdc = usdc_;
        poolBuilder = poolBuilder_;
        if (startMarketCap_ == 0) revert BadName();
        // review L-01: a zero minimum would let launches skip the first buy
        if (minLaunchBuy_ == 0) revert LaunchBuyTooSmall(0);
        startMarketCap = startMarketCap_;
        minLaunchBuy = minLaunchBuy_;
        admin = admin_;
        treasury = treasury_;
    }

    // ---------------------------------------------------------------- create

    /// @notice Creates a coin, opens its pool and makes the creator's launch buy
    /// (at least `minLaunchBuy`, at the normal 2% fee; approve the hub for that much USDC first).
    function createCoin(
        string calldata name,
        string calldata symbol,
        string calldata metadataURI,
        uint256 lockSeconds,
        FeeMode feeMode,
        uint256 launchUsdc,
        uint256 minCoinsOut
    ) external nonReentrant returns (address coin) {
        return _create(msg.sender, name, symbol, metadataURI, lockSeconds, feeMode, launchUsdc, minCoinsOut);
    }

    /// @notice Same as createCoin, for a creator who signed the request to the
    /// router (gasless launches). Only the router set by the admin may call it.
    /// The launch buy is paid by the router and the coins go to `creator`.
    function createCoinFor(
        address creator,
        string calldata name,
        string calldata symbol,
        string calldata metadataURI,
        uint256 lockSeconds,
        FeeMode feeMode,
        uint256 launchUsdc,
        uint256 minCoinsOut
    ) external nonReentrant returns (address coin) {
        if (msg.sender != router || creator == address(0)) revert NotAllowed();
        return _create(creator, name, symbol, metadataURI, lockSeconds, feeMode, launchUsdc, minCoinsOut);
    }

    function _create(
        address creator,
        string calldata name,
        string calldata symbol,
        string calldata metadataURI,
        uint256 lockSeconds,
        FeeMode feeMode,
        uint256 launchUsdc,
        uint256 minCoinsOut
    ) private returns (address coin) {
        uint256 nl = bytes(name).length;
        uint256 sl = bytes(symbol).length;
        if (nl == 0 || nl > 32 || sl == 0 || sl > 10) revert BadName();
        if (buysPaused) revert NotAllowed();
        if (launchUsdc < minLaunchBuy || launchUsdc == 0) revert LaunchBuyTooSmall(minLaunchBuy);

        // The whole supply is minted to the pool builder, which puts it all into the pool.
        coin = address(new ArkhamPadCoin(name, symbol, metadataURI, SUPPLY, address(poolBuilder), creator, lockSeconds));
        isCoin[coin] = true;
        allCoins.push(coin);
        emit CoinCreated(coin, creator, name, symbol, metadataURI, lockSeconds, feeMode);
        poolBuilder.launchPool(coin, SUPPLY, startMarketCap, creator, feeMode);

        usdc.safeTransferFrom(msg.sender, address(poolBuilder), launchUsdc);
        poolBuilder.launchBuy(coin, launchUsdc, minCoinsOut, creator);
    }

    function coinCount() external view returns (uint256) {
        return allCoins.length;
    }

    // ---------------------------------------------------------------- admin

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    function pauseBuys() external {
        if (msg.sender != admin && msg.sender != guardian) revert NotAllowed();
        buysPaused = true;
        emit BuysPaused(true);
    }

    function unpauseBuys() external onlyAdmin {
        buysPaused = false;
        emit BuysPaused(false);
    }

    function setTreasury(address t) external onlyAdmin {
        if (t == address(0)) revert ZeroAddress();
        treasury = t;
        emit TreasuryChanged(t);
    }

    /// @notice The gasless router allowed to call createCoinFor (zero turns it off).
    function setRouter(address r) external onlyAdmin {
        router = r;
        emit RouterChanged(r);
    }

    function setGuardian(address g) external onlyAdmin {
        guardian = g;
        emit GuardianChanged(g);
    }

    function proposeAdmin(address a) external onlyAdmin {
        pendingAdmin = a;
        emit AdminProposed(a);
    }

    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) revert NotAllowed();
        admin = pendingAdmin;
        pendingAdmin = address(0);
        emit AdminChanged(admin);
    }
}

src/PadLaunchHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {BeforeSwapDelta, BeforeSwapDeltaLibrary} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {LPFeeLibrary} from "@uniswap/v4-core/src/libraries/LPFeeLibrary.sol";
import {SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";

/// @title PadLaunchHook
/// @notice Uniswap v4 hook used by every ArkhamPad pool. It does two things only:
///   1. Nobody except the pool builder can create (initialize) a pool with this
///      hook, so no one can open a coin's pool early or at a bad price.
///   2. It sets the pool's trading fee. Every coin's pool opens at launch with a
///      fee of 30% that falls in a straight line to 2% over the first five
///      minutes, then stays at 2% forever. Bots that buy in the first seconds
///      pay the most. Swaps made by the pool builder itself (the creator's
///      launch buy and buybacks) always pay the normal 2%.
/// All fees go to the pool's only liquidity position, held and locked by the
/// pool builder, which splits them between the platform and the coin.
/// The hook holds no funds, never changes swap amounts and has no owner.
/// Deployed with CREATE2 so its address carries only the before-initialize and
/// before-swap flags.
contract PadLaunchHook {
    using PoolIdLibrary for PoolKey;

    /// @notice Fee units: 1_000_000 = 100%.
    uint24 public constant START_FEE = 300_000; // 30%
    uint24 public constant BASE_FEE = 20_000; // 2%
    uint256 public constant DECAY_SECONDS = 300; // five minutes

    address public immutable poolManager;
    address public immutable builder;

    /// @notice When each pool was created (its launch).
    mapping(PoolId => uint256) public launchedAt;

    error NotPoolManager();
    error NotBuilder();
    error NotAPadPool();

    constructor(address poolManager_, address builder_) {
        poolManager = poolManager_;
        builder = builder_;
    }

    /// @notice The fee a swap would pay right now, for a pool launched at `start`.
    function feeAt(uint256 start, uint256 nowTs) public pure returns (uint24) {
        if (nowTs <= start) return START_FEE; // review I-01: a time before the launch is the launch fee
        if (nowTs >= start + DECAY_SECONDS) return BASE_FEE;
        uint256 elapsed = nowTs - start;
        return uint24(START_FEE - ((uint256(START_FEE - BASE_FEE) * elapsed) / DECAY_SECONDS));
    }

    /// @notice The fee a swap in this pool pays right now.
    function currentFee(PoolKey calldata key) external view returns (uint24) {
        uint256 start = launchedAt[key.toId()];
        if (start == 0) return BASE_FEE;
        return feeAt(start, block.timestamp);
    }

    function beforeInitialize(address sender, PoolKey calldata key, uint160) external returns (bytes4) {
        if (msg.sender != poolManager) revert NotPoolManager();
        if (sender != builder) revert NotBuilder();
        launchedAt[key.toId()] = block.timestamp;
        return IHooks.beforeInitialize.selector;
    }

    function beforeSwap(address sender, PoolKey calldata key, SwapParams calldata, bytes calldata)
        external
        view
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        if (msg.sender != poolManager) revert NotPoolManager();
        uint256 start = launchedAt[key.toId()];
        if (start == 0) revert NotAPadPool();
        uint24 fee = sender == builder ? BASE_FEE : feeAt(start, block.timestamp);
        return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, fee | LPFeeLibrary.OVERRIDE_FEE_FLAG);
    }

}

src/PadPoolBuilder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {IPositionManager} from "@uniswap/v4-periphery/src/interfaces/IPositionManager.sol";
import {Actions} from "@uniswap/v4-periphery/src/libraries/Actions.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
import {IAllowanceTransfer} from "permit2/src/interfaces/IAllowanceTransfer.sol";

import {IPadHub, IPadPoolBuilder} from "./interfaces.sol";
import {FeeMode} from "./PadTypes.sol";
import {PadLaunchHook} from "./PadLaunchHook.sol";
import {LPFeeLibrary} from "@uniswap/v4-core/src/libraries/LPFeeLibrary.sol";

/// @title PadPoolBuilder
/// @notice Opens every new ArkhamPad coin straight into a Uniswap v4 coin/USDC
/// pool at launch. The coin's whole supply goes into one liquidity position
/// that starts at the launch price and reaches every higher price, so the pool
/// sells coins as people buy, like a bonding curve, but as a normal Uniswap pool
/// that DEX screeners, aggregators and trading apps see from the first trade.
/// The position NFT stays in this contract, which has no way to remove
/// liquidity or move it: the liquidity is locked forever.
///
/// The pool's fee is set by PadLaunchHook: 30% at launch, falling to 2% over
/// five minutes, then 2% forever. All of it accrues to the locked position.
/// Pool trading fees can be collected by anyone with `collectFees(coin)`.
/// They are split 70% to the platform treasury and 30% to the coin:
///   - fee mode ToCreator:   paid to the coin's creator,
///   - fee mode BuybackBurn: USDC is kept to buy the coin back and burn it,
///                           coin fees are burned straight away.
/// Fees in both currencies are split the same way.
contract PadPoolBuilder is IPadPoolBuilder, IUnlockCallback, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice The fee is dynamic: PadLaunchHook sets it on every swap.
    uint24 public constant POOL_FEE = LPFeeLibrary.DYNAMIC_FEE_FLAG;
    int24 public constant TICK_SPACING = 200;
    uint256 public constant BPS = 10_000;
    uint256 public constant COIN_CUT_BPS = 3_000; // 30% of pool fees to the coin side
    /// @notice Most USDC one buyback call spends in the pool.
    /// @notice Most USDC one buyback call spends ($100, in the dollar token's own decimals).
    uint256 public immutable MAX_BUYBACK_STEP;
    /// @dev Set only while this builder itself is inside PoolManager.unlock.
    bool private _unlocking;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    IPoolManager public immutable poolManager;
    IPositionManager public immutable positionManager;
    IAllowanceTransfer public immutable permit2;
    IERC20 public immutable usdc;
    PadLaunchHook public immutable guard;
    address private immutable _deployer;

    IPadHub public hub;

    struct Pool {
        uint256 positionId;
        address creator;
        FeeMode feeMode;
    }

    mapping(address coin => Pool) public pools;
    /// @notice USDC waiting to buy back and burn a coin.
    mapping(address coin => uint256) public buybackFunds;
    /// @notice USDC a recipient could not receive when it was sent; claim with `claimOwed`.
    mapping(address who => uint256) public owed;
    /// @dev USDC held for others (buyback funds + owed + dust); never part of a new pool.
    uint256 public usdcHeld;

    event PoolBuilt(address indexed coin, uint256 indexed positionId, uint256 usdcIn, uint256 coinsIn, uint160 sqrtPriceX96);
    event FeesCollected(address indexed coin, uint256 usdcFees, uint256 coinFees);
    event BuybackFunded(address indexed coin, uint256 amount);
    event BuybackDone(address indexed coin, uint256 usdcSpent, uint256 coinsBurned);
    event Owed(address indexed who, uint256 amount);

    error ZeroAddress();
    error NotDeployer();
    error AlreadyBound();
    error NotHub();
    error AlreadyBuilt();
    error NotBuilt();
    error NothingToDo();
    error NotDelivered();
    error BadGuardAddress(address guard);
    error NotPoolManager();
    error NotUnlocking();
    error Slippage(uint256 got, uint256 minimum);

    constructor(
        IPoolManager poolManager_,
        IPositionManager positionManager_,
        IAllowanceTransfer permit2_,
        IERC20 usdc_,
        bytes32 guardSalt
    ) {
        if (
            address(poolManager_) == address(0) || address(positionManager_) == address(0) || address(permit2_) == address(0)
                || address(usdc_) == address(0)
        ) revert ZeroAddress();
        poolManager = poolManager_;
        positionManager = positionManager_;
        MAX_BUYBACK_STEP = 100 * 10 ** IERC20Metadata(address(usdc_)).decimals();
        permit2 = permit2_;
        usdc = usdc_;
        _deployer = msg.sender;
        guard = new PadLaunchHook{salt: guardSalt}(address(poolManager_), address(this));
        if (uint160(address(guard)) & Hooks.ALL_HOOK_MASK != (Hooks.BEFORE_INITIALIZE_FLAG | Hooks.BEFORE_SWAP_FLAG)) {
            revert BadGuardAddress(address(guard));
        }
    }

    /// @notice Links the hub once, right after deployment (the hub needs this
    /// contract's address first, so they cannot be set in one constructor).
    function bindHub(IPadHub hub_) external {
        if (msg.sender != _deployer) revert NotDeployer();
        if (address(hub) != address(0)) revert AlreadyBound();
        if (address(hub_) == address(0)) revert ZeroAddress();
        hub = hub_;
    }

    // ---------------------------------------------------------------- pool

    function usdcIsCurrency0(address coin) public view returns (bool) {
        return address(usdc) < coin;
    }

    function poolKeyFor(address coin) public view returns (PoolKey memory) {
        bool u0 = usdcIsCurrency0(coin);
        return PoolKey({
            currency0: Currency.wrap(u0 ? address(usdc) : coin),
            currency1: Currency.wrap(u0 ? coin : address(usdc)),
            fee: POOL_FEE,
            tickSpacing: TICK_SPACING,
            hooks: IHooks(address(guard))
        });
    }

    /// @inheritdoc IPadPoolBuilder
    /// @dev Called by the hub right after it minted the coin's supply to this contract.
    function launchPool(address coin, uint256 coinAmount, uint256 startMarketCap, address creator, FeeMode feeMode)
        external
        nonReentrant
    {
        if (msg.sender != address(hub) || address(hub) == address(0)) revert NotHub();
        if (pools[coin].positionId != 0) revert AlreadyBuilt();
        if (coinAmount == 0 || startMarketCap == 0) revert NothingToDo();
        if (IERC20(coin).balanceOf(address(this)) < coinAmount) revert NotDelivered();

        PoolKey memory key = poolKeyFor(coin);
        bool u0 = usdcIsCurrency0(coin);
        uint256 supply = IERC20(coin).totalSupply();

        // Launch price: startMarketCap USDC for the whole supply. The position
        // holds only coins and covers every price from the launch price up.
        int24 lower;
        int24 upper;
        uint160 startSqrtPrice;
        uint128 liquidity;
        if (!u0) {
            // coin is currency0, price = USDC per coin: coins sit above the start.
            int24 t = TickMath.getTickAtSqrtPrice(_sqrtPriceX96(supply, startMarketCap));
            lower = _roundUp(t);
            upper = TickMath.maxUsableTick(TICK_SPACING);
            startSqrtPrice = TickMath.getSqrtPriceAtTick(lower);
            liquidity = LiquidityAmounts.getLiquidityForAmount0(startSqrtPrice, TickMath.getSqrtPriceAtTick(upper), coinAmount);
        } else {
            // coin is currency1, price = coins per USDC: coins sit below the start.
            int24 t = TickMath.getTickAtSqrtPrice(_sqrtPriceX96(startMarketCap, supply));
            upper = _roundDown(t);
            lower = TickMath.minUsableTick(TICK_SPACING);
            startSqrtPrice = TickMath.getSqrtPriceAtTick(upper);
            liquidity = LiquidityAmounts.getLiquidityForAmount1(TickMath.getSqrtPriceAtTick(lower), startSqrtPrice, coinAmount);
        }
        if (liquidity == 0) revert NothingToDo();
        poolManager.initialize(key, startSqrtPrice);

        _approve(coin, coinAmount);
        uint256 coinBefore = IERC20(coin).balanceOf(address(this));
        uint256 positionId = positionManager.nextTokenId();

        bytes memory actions = abi.encodePacked(uint8(Actions.MINT_POSITION), uint8(Actions.SETTLE_PAIR));
        bytes[] memory params = new bytes[](2);
        params[0] = abi.encode(
            key, lower, upper, uint256(liquidity), u0 ? 0 : coinAmount, u0 ? coinAmount : 0, address(this), bytes("")
        );
        params[1] = abi.encode(key.currency0, key.currency1);
        positionManager.modifyLiquidities(abi.encode(actions, params), block.timestamp);
        _approve(coin, 0);

        // Rounding dust is burned: no coin is ever held outside the pool.
        uint256 coinUsed = coinBefore - IERC20(coin).balanceOf(address(this));
        if (coinAmount > coinUsed) IERC20(coin).safeTransfer(BURN, coinAmount - coinUsed);

        pools[coin] = Pool({positionId: positionId, creator: creator, feeMode: feeMode});
        emit PoolBuilt(coin, positionId, 0, coinUsed, startSqrtPrice);
    }

    /// @inheritdoc IPadPoolBuilder
    /// @dev The hub sends `usdcAmount` here first. The swap is made by this
    /// contract, so it pays the normal 2% fee, not the launch fee.
    function launchBuy(address coin, uint256 usdcAmount, uint256 minCoinsOut, address to)
        external
        nonReentrant
        returns (uint256 coinsOut)
    {
        if (msg.sender != address(hub) || address(hub) == address(0)) revert NotHub();
        if (pools[coin].positionId == 0) revert NotBuilt();
        if (usdcAmount == 0) revert NothingToDo();
        if (usdc.balanceOf(address(this)) < usdcHeld + usdcAmount) revert NotDelivered();
        _unlocking = true;
        uint256 spent;
        (coinsOut, spent) = abi.decode(poolManager.unlock(abi.encode(coin, usdcAmount, to)), (uint256, uint256));
        _unlocking = false;
        if (coinsOut < minCoinsOut) revert Slippage(coinsOut, minCoinsOut);
        if (spent < usdcAmount) _payUsdc(to, usdcAmount - spent);
    }

    // ---------------------------------------------------------------- fees

    /// @notice Collects a graduated coin's pool fees and splits them. Anyone can call.
    function collectFees(address coin) external nonReentrant returns (uint256 usdcFees, uint256 coinFees) {
        Pool memory p = pools[coin];
        if (p.positionId == 0) revert NotBuilt();
        PoolKey memory key = poolKeyFor(coin);

        uint256 usdcBefore = usdc.balanceOf(address(this));
        uint256 coinBefore = IERC20(coin).balanceOf(address(this));

        bytes memory actions = abi.encodePacked(uint8(Actions.DECREASE_LIQUIDITY), uint8(Actions.TAKE_PAIR));
        bytes[] memory params = new bytes[](2);
        params[0] = abi.encode(p.positionId, uint256(0), uint128(0), uint128(0), bytes(""));
        params[1] = abi.encode(key.currency0, key.currency1, address(this));
        positionManager.modifyLiquidities(abi.encode(actions, params), block.timestamp);

        usdcFees = usdc.balanceOf(address(this)) - usdcBefore;
        coinFees = IERC20(coin).balanceOf(address(this)) - coinBefore;
        emit FeesCollected(coin, usdcFees, coinFees);

        address treasury = hub.treasury();
        if (usdcFees > 0) {
            uint256 toCoin = (usdcFees * COIN_CUT_BPS) / BPS;
            _payUsdc(treasury, usdcFees - toCoin);
            if (p.feeMode == FeeMode.BuybackBurn) {
                buybackFunds[coin] += toCoin;
                usdcHeld += toCoin;
                emit BuybackFunded(coin, toCoin);
            } else {
                _payUsdc(p.creator, toCoin);
            }
        }
        if (coinFees > 0) {
            uint256 toCoin = (coinFees * COIN_CUT_BPS) / BPS;
            IERC20(coin).safeTransfer(treasury, coinFees - toCoin);
            if (p.feeMode == FeeMode.BuybackBurn) {
                IERC20(coin).safeTransfer(BURN, toCoin);
            } else {
                _payCoin(coin, p.creator, toCoin);
            }
        }
    }

    /// @notice Spends up to MAX_BUYBACK_STEP of a coin's buyback money in its
    /// pool and burns the coins bought. Anyone can call.
    function buyback(address coin) external nonReentrant returns (uint256 spent, uint256 burned) {
        if (pools[coin].positionId == 0) revert NotBuilt();
        spent = Math.min(buybackFunds[coin], MAX_BUYBACK_STEP);
        if (spent == 0) revert NothingToDo();
        buybackFunds[coin] -= spent;
        usdcHeld -= spent;
        _unlocking = true;
        uint256 paid;
        (burned, paid) = abi.decode(poolManager.unlock(abi.encode(coin, spent, BURN)), (uint256, uint256));
        _unlocking = false;
        // An exact-input swap can stop at the price limit with input left over.
        if (paid < spent) {
            buybackFunds[coin] += spent - paid;
            usdcHeld += spent - paid;
            spent = paid;
        }
        emit BuybackDone(coin, spent, burned);
    }

    /// @dev Swap USDC -> coin inside the pool manager's lock; coins go to `to`
    /// (the burn address for buybacks, the creator for a launch buy).
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        if (!_unlocking) revert NotUnlocking(); // only our own buyback or launch buy may run a swap here
        (address coin, uint256 amountIn, address to) = abi.decode(data, (address, uint256, address));
        PoolKey memory key = poolKeyFor(coin);
        bool zeroForOne = usdcIsCurrency0(coin);
        BalanceDelta delta = poolManager.swap(
            key,
            SwapParams({
                zeroForOne: zeroForOne,
                amountSpecified: -int256(amountIn),
                sqrtPriceLimitX96: zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1
            }),
            bytes("")
        );
        int128 usdcDelta = zeroForOne ? delta.amount0() : delta.amount1();
        int128 coinDelta = zeroForOne ? delta.amount1() : delta.amount0();
        uint256 pay = uint256(uint128(-usdcDelta));
        uint256 out = uint256(uint128(coinDelta));

        Currency u = Currency.wrap(address(usdc));
        poolManager.sync(u);
        usdc.safeTransfer(address(poolManager), pay);
        poolManager.settle();
        poolManager.take(Currency.wrap(coin), to, out);
        return abi.encode(out, pay);
    }

    /// @notice Pays out USDC that could not be sent earlier.
    function claimOwed() external nonReentrant {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingToDo();
        owed[msg.sender] = 0;
        usdcHeld -= a;
        usdc.safeTransfer(msg.sender, a);
    }

    // ---------------------------------------------------------------- helpers

    function _payUsdc(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, bytes memory ret) = address(usdc).call(abi.encodeCall(IERC20.transfer, (to, amount)));
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) {
            owed[to] += amount;
            usdcHeld += amount;
            emit Owed(to, amount);
        }
    }

    function _payCoin(address coin, address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, bytes memory ret) = coin.call(abi.encodeCall(IERC20.transfer, (to, amount)));
        // A creator who can't receive (e.g. still locked is fine; receiving is never locked) - burn instead.
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) IERC20(coin).safeTransfer(BURN, amount);
    }

    function _approve(address token, uint256 amount) private {
        if (amount > 0) IERC20(token).forceApprove(address(permit2), type(uint256).max);
        else IERC20(token).forceApprove(address(permit2), 0);
        permit2.approve(token, address(positionManager), uint160(amount), uint48(block.timestamp));
    }

    function _roundUp(int24 t) private pure returns (int24) {
        int24 r = _roundDown(t);
        return r < t ? r + TICK_SPACING : r;
    }

    function _roundDown(int24 t) private pure returns (int24) {
        int24 r = (t / TICK_SPACING) * TICK_SPACING;
        if (t < 0 && r != t) r -= TICK_SPACING;
        return r;
    }

    /// @dev sqrt(amount1 / amount0) in Q64.96, i.e. price of currency0 in currency1.
    function _sqrtPriceX96(uint256 amount0, uint256 amount1) private pure returns (uint160) {
        uint256 s;
        if (amount1 / amount0 < (1 << 63)) {
            // sqrt(amount1 * 2^192 / amount0): the ratio fits, full precision.
            s = Math.sqrt(Math.mulDiv(amount1, 1 << 192, amount0));
        } else {
            // Very large ratio: sqrt(amount1 * 2^96 / amount0) * 2^48 avoids overflow.
            s = Math.sqrt(Math.mulDiv(amount1, 1 << 96, amount0)) << 48;
        }
        if (s < TickMath.MIN_SQRT_PRICE) s = TickMath.MIN_SQRT_PRICE;
        if (s >= TickMath.MAX_SQRT_PRICE) s = TickMath.MAX_SQRT_PRICE - 1;
        return uint160(s);
    }
}

src/PadPromote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title PadPromote
/// @notice Pays to show any coin (launched on ArkhamPad or not) in the
/// Promoted row for a while. Anyone can promote any coin. Payment in USDC goes
/// straight to the treasury; the site reads the events to show the row.
contract PadPromote {
    using SafeERC20 for IERC20;

    struct Plan {
        uint64 seconds_;
        uint128 price; // USDC, 6 decimals
        bool active;
    }

    IERC20 public immutable usdc;
    address public admin;
    address public treasury;
    mapping(uint8 => Plan) public plans;

    event Promoted(address indexed coin, uint256 indexed chainId, address indexed payer, uint8 plan, uint256 seconds_, uint256 price);
    event PlanSet(uint8 indexed plan, uint256 seconds_, uint256 price, bool active);
    event TreasuryChanged(address treasury);
    event AdminChanged(address admin);

    error NotAdmin();
    error NoSuchPlan();
    error ZeroAddress();

    constructor(IERC20 usdc_, address admin_, address treasury_) {
        if (address(usdc_) == address(0) || admin_ == address(0) || treasury_ == address(0)) revert ZeroAddress();
        usdc = usdc_;
        admin = admin_;
        treasury = treasury_;
        // 6 hours $10, 24 hours $20, 7 days $99 (in the dollar token's own decimals)
        uint256 d = 10 ** IERC20Metadata(address(usdc_)).decimals();
        _setPlan(1, 6 hours, uint128(10 * d), true);
        _setPlan(2, 24 hours, uint128(20 * d), true);
        _setPlan(3, 7 days, uint128(99 * d), true);
    }

    /// @notice Promotes `coin` (a coin on chain `chainId`; any chain the site lists).
    function promote(address coin, uint256 chainId, uint8 plan) external {
        Plan memory p = plans[plan];
        if (!p.active || coin == address(0)) revert NoSuchPlan();
        emit Promoted(coin, chainId, msg.sender, plan, p.seconds_, p.price);
        usdc.safeTransferFrom(msg.sender, treasury, p.price);
    }

    function setPlan(uint8 plan, uint64 seconds_, uint128 price, bool active) external {
        if (msg.sender != admin) revert NotAdmin();
        _setPlan(plan, seconds_, price, active);
    }

    function setTreasury(address t) external {
        if (msg.sender != admin) revert NotAdmin();
        if (t == address(0)) revert ZeroAddress();
        treasury = t;
        emit TreasuryChanged(t);
    }

    function setAdmin(address a) external {
        if (msg.sender != admin) revert NotAdmin();
        if (a == address(0)) revert ZeroAddress();
        admin = a;
        emit AdminChanged(a);
    }

    function _setPlan(uint8 plan, uint64 s, uint128 price, bool active) private {
        plans[plan] = Plan(s, price, active);
        emit PlanSet(plan, s, price, active);
    }
}

src/PadRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {PadHub} from "./PadHub.sol";
import {FeeMode} from "./PadTypes.sol";
import {PadPromote} from "./PadPromote.sol";
import {PadPoolBuilder} from "./PadPoolBuilder.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";

/// @title PadRouter
/// @notice Gasless trading. A user signs what they want (buy, sell, launch,
/// withdraw, promote); anyone (normally the ArkhamPad relayer) submits it and
/// pays the network gas. The user pays that gas back in USDC: the `fee` they
/// signed is sent to the submitter. Users never need ETH.
///
/// Safety:
///  - Every request is signed by the user (EIP-712) and names the exact amounts,
///    the fee, a deadline and a one-time nonce. Nothing else can be done with a user's funds.
///  - Prices are protected on-chain by minimum-out amounts the user signed, so a
///    delayed order (limit / take profit / stop loss) can never fill worse than signed.
///  - The router holds no money between calls; leftovers are returned in the same call.
contract PadRouter is EIP712, ReentrancyGuard, IUnlockCallback {
    using SafeERC20 for IERC20;

    bytes32 public constant CREATE_TYPEHASH = keccak256(
        "Create(address user,string name,string symbol,string metadataURI,uint256 lockSeconds,uint8 feeMode,uint256 launchUsdc,uint256 minCoinsOut,uint256 fee,uint256 nonce,uint256 deadline)"
    );
    bytes32 public constant WITHDRAW_TYPEHASH =
        keccak256("Withdraw(address user,address to,uint256 amount,uint256 fee,uint256 nonce,uint256 deadline)");
    bytes32 public constant PROMOTE_TYPEHASH = keccak256(
        "Promote(address user,address coin,uint256 coinChainId,uint8 plan,uint256 maxPrice,uint256 fee,uint256 nonce,uint256 deadline)"
    );
    bytes32 public constant CANCEL_TYPEHASH = keccak256("Cancel(address user,uint256 nonce)");
    bytes32 public constant POOL_BUY_TYPEHASH =
        keccak256("PoolBuy(address user,address coin,uint256 usdcIn,uint256 minCoinsOut,uint256 fee,uint256 nonce,uint256 deadline)");
    bytes32 public constant POOL_SELL_TYPEHASH =
        keccak256("PoolSell(address user,address coin,uint256 coinAmount,uint256 minUsdcOut,uint256 fee,uint256 nonce,uint256 deadline)");

    PadHub public immutable hub;
    IERC20 public immutable usdc;
    PadPromote public immutable promoter;
    /// @notice Opens and holds every coin's locked pool (zero: pool trading off).
    PadPoolBuilder public immutable builder;
    IPoolManager public immutable poolManager;
    /// @dev Set only while this router itself is inside PoolManager.unlock, so nobody else can
    /// make the PoolManager call our callback.
    bool private _unlocking;

    /// @notice user => nonce => used (any order of use, so many open orders can coexist)
    mapping(address => mapping(uint256 => bool)) public nonceUsed;

    event Launched(address indexed user, address indexed coin, uint256 launchUsdc, uint256 fee, uint256 nonce);
    event Withdrawn(address indexed user, address indexed to, uint256 amount, uint256 fee, uint256 nonce);
    event Promoted(address indexed user, address indexed coin, uint8 plan, uint256 fee, uint256 nonce);
    event NonceCancelled(address indexed user, uint256 nonce);
    event Swept(address indexed token, address indexed to, uint256 amount);
    event PoolTraded(address indexed user, address indexed coin, bool isBuy, uint256 usdcAmount, uint256 coinAmount, uint256 fee, uint256 nonce);

    error Expired();
    error NonceAlreadyUsed();
    error BadSignature();
    error FeeTooHigh();
    error Slippage(uint256 got, uint256 minimum);
    error ZeroAddress();
    error NoPool();
    error OnlyPoolManager();
    error Quote(uint256 amountOut);
    error NotUnlocking();
    error NotAdmin();

    struct Sig {
        uint256 deadline;
        uint256 nonce;
        bytes signature;
    }

    constructor(PadHub hub_, PadPromote promoter_, PadPoolBuilder builder_) EIP712("ArkhamPad", "1") {
        if (address(hub_) == address(0)) revert ZeroAddress();
        hub = hub_;
        usdc = hub_.usdc();
        promoter = promoter_;
        builder = builder_;
        poolManager = address(builder_) == address(0) ? IPoolManager(address(0)) : builder_.poolManager();
    }

    // ---------------------------------------------------------------- approvals by signature

    /// @notice Submits an EIP-2612 permit (USDC or a coin) for the router.
    /// Never reverts on failure: a permit can be front-run, and the allowance
    /// it sets may already be in place.
    function permit(address token, address owner, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        try IERC20Permit(token).permit(owner, address(this), value, deadline, v, r, s) {} catch {}
    }

    // ---------------------------------------------------------------- trading

    struct Launch {
        string name;
        string symbol;
        string metadataURI;
        uint256 lockSeconds;
        FeeMode feeMode;
        uint256 launchUsdc;
        uint256 minCoinsOut;
    }

    function launch(address user, Launch calldata l, uint256 fee, Sig calldata sig)
        external
        nonReentrant
        returns (address coin)
    {
        bytes32 h = _launchHash(user, l, fee, sig);
        _use(user, sig, h);

        if (l.launchUsdc + fee > 0) usdc.safeTransferFrom(user, address(this), l.launchUsdc + fee);
        if (fee > 0) usdc.safeTransfer(msg.sender, fee);

        uint256 spent;
        (coin, spent) = _createFor(user, l);
        emit Launched(user, coin, spent, fee, sig.nonce);
    }

    // ---------------------------------------------------------------- trading (each coin's locked Uniswap v4 pool)

    /// @notice Buys a coin in its locked pool with USDC: signed by the user,
    /// network fee paid back in USDC, never fills below minCoinsOut.
    function poolBuy(address user, address coin, uint256 usdcIn, uint256 minCoinsOut, uint256 fee, Sig calldata sig)
        external
        nonReentrant
        returns (uint256 coinsOut)
    {
        _use(user, sig, keccak256(abi.encode(POOL_BUY_TYPEHASH, user, coin, usdcIn, minCoinsOut, fee, sig.nonce, sig.deadline)));
        _requirePool(coin);
        usdc.safeTransferFrom(user, address(this), usdcIn + fee);
        if (fee > 0) usdc.safeTransfer(msg.sender, fee);
        uint256 paid;
        (coinsOut, paid) = _poolSwap(coin, true, usdcIn);
        if (coinsOut < minCoinsOut) revert Slippage(coinsOut, minCoinsOut);
        if (paid < usdcIn) usdc.safeTransfer(user, usdcIn - paid); // only part could be swapped
        IERC20(coin).safeTransfer(user, coinsOut);
        emit PoolTraded(user, coin, true, usdcIn, coinsOut, fee, sig.nonce);
    }

    /// @notice Sells a coin in its locked pool for USDC (fee taken from the USDC out).
    function poolSell(address user, address coin, uint256 coinAmount, uint256 minUsdcOut, uint256 fee, Sig calldata sig)
        external
        nonReentrant
        returns (uint256 usdcToUser)
    {
        _use(user, sig, keccak256(abi.encode(POOL_SELL_TYPEHASH, user, coin, coinAmount, minUsdcOut, fee, sig.nonce, sig.deadline)));
        _requirePool(coin);
        IERC20(coin).safeTransferFrom(user, address(this), coinAmount);
        (uint256 out, uint256 paid) = _poolSwap(coin, false, coinAmount);
        if (paid < coinAmount) IERC20(coin).safeTransfer(user, coinAmount - paid);
        if (out < fee) revert FeeTooHigh();
        usdcToUser = out - fee;
        if (usdcToUser < minUsdcOut) revert Slippage(usdcToUser, minUsdcOut);
        if (fee > 0) usdc.safeTransfer(msg.sender, fee);
        usdc.safeTransfer(user, usdcToUser);
        emit PoolTraded(user, coin, false, out, coinAmount, fee, sig.nonce);
    }

    /// @notice What a pool trade would return right now. Not a view: call it with eth_call.
    /// The swap is simulated inside the pool and undone (it always reverts internally).
    function quotePool(address coin, bool isBuy, uint256 amountIn) external returns (uint256 amountOut) {
        _requirePool(coin);
        _unlocking = true;
        try poolManager.unlock(abi.encode(coin, isBuy, amountIn, true)) {
            _unlocking = false;
            return 0; // unreachable: a quote always reverts with the result
        } catch (bytes memory err) {
            _unlocking = false;
            if (err.length == 36 && bytes4(err) == Quote.selector) {
                assembly { amountOut := mload(add(err, 36)) }
                return amountOut;
            }
            assembly { revert(add(err, 32), mload(err)) }
        }
    }

    /// @notice Returns tokens someone sent to the router by mistake. The router holds nothing
    /// between transactions, so this can never touch a user's trade. Hub admin only.
    function sweep(address token, address to) external nonReentrant {
        if (msg.sender != hub.admin()) revert NotAdmin();
        if (to == address(0)) revert ZeroAddress();
        uint256 bal = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransfer(to, bal);
        emit Swept(token, to, bal);
    }

    function _requirePool(address coin) private view {
        if (address(poolManager) == address(0) || !hub.isCoin(coin)) revert NoPool();
        (uint256 positionId,,) = builder.pools(coin);
        if (positionId == 0) revert NoPool();
    }

    function _poolSwap(address coin, bool usdcIn, uint256 amountIn) private returns (uint256 out, uint256 paid) {
        _unlocking = true;
        (out, paid) = abi.decode(poolManager.unlock(abi.encode(coin, usdcIn, amountIn, false)), (uint256, uint256));
        _unlocking = false;
    }

    /// @dev Exact-input swap; the router pays in and receives the output itself.
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert OnlyPoolManager();
        if (!_unlocking) revert NotUnlocking();
        (address coin, bool usdcIn, uint256 amountIn, bool quote) = abi.decode(data, (address, bool, uint256, bool));
        PoolKey memory key = builder.poolKeyFor(coin);
        bool usdcIs0 = Currency.unwrap(key.currency0) == address(usdc);
        bool zeroForOne = usdcIn ? usdcIs0 : !usdcIs0;
        BalanceDelta d = poolManager.swap(
            key,
            SwapParams({zeroForOne: zeroForOne, amountSpecified: -int256(amountIn), sqrtPriceLimitX96: zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1}),
            ""
        );
        int128 inD = zeroForOne ? d.amount0() : d.amount1();
        int128 outD = zeroForOne ? d.amount1() : d.amount0();
        uint256 pay = uint256(uint128(-inD));
        uint256 out = uint256(uint128(outD));
        if (quote) revert Quote(out);
        (Currency inC, Currency outC) = zeroForOne ? (key.currency0, key.currency1) : (key.currency1, key.currency0);
        poolManager.sync(inC);
        IERC20(Currency.unwrap(inC)).safeTransfer(address(poolManager), pay);
        poolManager.settle();
        poolManager.take(outC, address(this), out);
        return abi.encode(out, pay);
    }

    // ---------------------------------------------------------------- money out, promote, cancel

    function withdraw(address user, address to, uint256 amount, uint256 fee, Sig calldata sig) external nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        _use(user, sig, keccak256(abi.encode(WITHDRAW_TYPEHASH, user, to, amount, fee, sig.nonce, sig.deadline)));
        usdc.safeTransferFrom(user, to, amount);
        if (fee > 0) usdc.safeTransferFrom(user, msg.sender, fee);
        emit Withdrawn(user, to, amount, fee, sig.nonce);
    }

    function promote(address user, address coin, uint256 coinChainId, uint8 plan, uint256 maxPrice, uint256 fee, Sig calldata sig)
        external
        nonReentrant
    {
        _use(user, sig, keccak256(abi.encode(PROMOTE_TYPEHASH, user, coin, coinChainId, plan, maxPrice, fee, sig.nonce, sig.deadline)));
        (, uint128 price,) = promoter.plans(plan);
        if (price > maxPrice) revert Slippage(maxPrice, price);
        usdc.safeTransferFrom(user, address(this), uint256(price) + fee);
        if (fee > 0) usdc.safeTransfer(msg.sender, fee);
        usdc.forceApprove(address(promoter), price);
        promoter.promote(coin, coinChainId, plan);
        usdc.forceApprove(address(promoter), 0);
        emit Promoted(user, coin, plan, fee, sig.nonce);
    }

    /// @notice Cancels an open (signed but unsent) order. The user can call it
    /// directly, or sign a Cancel and let anyone submit it.
    function cancel(address user, uint256 nonce, bytes calldata signature) external {
        if (msg.sender != user) {
            bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(CANCEL_TYPEHASH, user, nonce)));
            if (!SignatureChecker.isValidSignatureNow(user, digest, signature)) revert BadSignature();
        }
        if (nonceUsed[user][nonce]) revert NonceAlreadyUsed();
        nonceUsed[user][nonce] = true;
        emit NonceCancelled(user, nonce);
    }

    // ---------------------------------------------------------------- views / internal

    function domainSeparator() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    /// @dev Creates the coin through the hub, paying the launch buy; returns any unspent USDC to the user.
    function _createFor(address user, Launch calldata l) private returns (address coin, uint256 spent) {
        uint256 before = usdc.balanceOf(address(this));
        if (l.launchUsdc > 0) usdc.forceApprove(address(hub), l.launchUsdc);
        coin = hub.createCoinFor(user, l.name, l.symbol, l.metadataURI, l.lockSeconds, l.feeMode, l.launchUsdc, l.minCoinsOut);
        if (l.launchUsdc > 0) usdc.forceApprove(address(hub), 0);
        spent = before - usdc.balanceOf(address(this));
        if (spent < l.launchUsdc) usdc.safeTransfer(user, l.launchUsdc - spent);
    }

    /// @dev EIP-712 struct hash of a Create request. abi.encode of fixed-size
    /// values is plain concatenation, so it is built in two halves (fewer
    /// values on the stack at once); the result is identical.
    function _launchHash(address user, Launch calldata l, uint256 fee, Sig calldata sig) private pure returns (bytes32) {
        bytes memory head = _launchHead(user, l);
        bytes memory tail = abi.encode(l.lockSeconds, uint8(l.feeMode), l.launchUsdc, l.minCoinsOut, fee, sig.nonce, sig.deadline);
        return keccak256(bytes.concat(head, tail));
    }

    function _launchHead(address user, Launch calldata l) private pure returns (bytes memory) {
        bytes32 n = keccak256(bytes(l.name));
        bytes32 sy = keccak256(bytes(l.symbol));
        bytes32 u = keccak256(bytes(l.metadataURI));
        return abi.encode(CREATE_TYPEHASH, user, n, sy, u);
    }

    function _use(address user, Sig calldata sig, bytes32 structHash) private {
        if (block.timestamp > sig.deadline) revert Expired();
        if (nonceUsed[user][sig.nonce]) revert NonceAlreadyUsed();
        if (!SignatureChecker.isValidSignatureNow(user, _hashTypedDataV4(structHash), sig.signature)) revert BadSignature();
        nonceUsed[user][sig.nonce] = true;
    }
}

